def normalize_capability_type(value):
    if not isinstance(value, str):
        return None
    v = value.strip().lower()
    if v in {'tool', 'resource', 'prompt'}:
        return v
    return None

def discover_enabled(items):
    result = []
    for item in items:
        if item.get('enabled'):
            result.append(item.get('name'))
    return result

def validate_tool_call(call, required_keys):
    if not isinstance(call, dict):
        return [False, 'invalid_shape']
    if not isinstance(call.get('tool'), str) or not isinstance(call.get('args'), dict):
        return [False, 'invalid_shape']
    args = call.get('args', {})
    for key in required_keys:
        if key not in args:
            return [False, 'missing_required_arg']
    return [True, 'ok']

def is_allowed(role, tool_name, policy):
    allowed_roles = policy.get(tool_name, [])
    return role in allowed_roles

def build_audit_event(actor, tool, ok, error=None):
    event = {
        'actor': actor,
        'tool': tool,
        'status': 'success' if ok else 'failure',
    }
    if not ok:
        event['error'] = error
    return event

