class ToolRegistry:
    def __init__(self):
        self._tools = {}

    def register(self, name, description, required_args):
        self._tools[name] = {'name': name, 'description': description, 'required_args': required_args}
        return self

    def find(self, name):
        return self._tools.get(name)

    def validate_call(self, name, args):
        tool = self.find(name)
        if tool is None:
            return [False, 'unknown_tool']
        missing = [a for a in tool['required_args'] if a not in args]
        if missing:
            return [False, 'missing_args:' + ','.join(missing)]
        return [True, args]

    def list_tools(self):
        return sorted(self._tools.keys())

    def tool_count(self):
        return len(self._tools)
